1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.samples.petclinic.mapper.OwnerMapper;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.web.bind.annotation.RequestHeader;
10	
11	/**
12	 * First step of the create pipeline: when the request repeats an already-seen
13	 * {@code Idempotency-Key}, respond 200 with the originally created owner and skip the
14	 * create; otherwise proceed with the normal pipeline.
15	 */
16	public class CheckIdempotency {
17	
18	    @FunctionalInterface
19	    public interface Proceed {
20	        void run();
21	    }
22	
23	    public void service(@RequestHeader(name = "Idempotency-Key", required = false) String key,
24	            IdempotencyStore store, OwnerRepository ownerRepository, OwnerMapper ownerMapper,
25	            ObjectResponse<OwnerDto> response, @Flow("proceed") Proceed proceed) {
26	        Integer ownerId = key == null ? null : store.find(key);
27	        if (ownerId == null) {
28	            proceed.run();
29	            return;
30	        }
31	        Owner owner = ownerRepository.findById(ownerId);
32	        response.send(ownerMapper.toOwnerDto(owner)); // 200 by default
33	    }
34	}
