1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that omits or blanks any required owner field, before the body is
13	 * mapped, so each missing field becomes a 400 listing its name.
14	 */
15	public class ValidateOwnerFields {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
18	            throws MissingFieldsException {
19	        List<String> errors = new ArrayList<>();
20	        requireField(errors, "firstName", request.getFirstName());
21	        requireField(errors, "lastName", request.getLastName());
22	        if (isBlank(request.getAddressLine1()) && isBlank(request.getAddress())) {
23	            errors.add("address");
24	        }
25	        requireField(errors, "city", request.getCity());
26	        requireField(errors, "telephone", request.getTelephone());
27	        if (!errors.isEmpty()) {
28	            throw new MissingFieldsException(errors);
29	        }
30	        validated.set(request);
31	    }
32	
33	    private static void requireField(List<String> errors, String name, String value) {
34	        if (isBlank(value)) {
35	            errors.add(name);
36	        }
37	    }
38	
39	    private static boolean isBlank(String value) {
40	        return value == null || value.isBlank();
41	    }
42	}
