7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
10	
11	/**
12	 * Rejects a create request whose email domain is on the disposable-domain blocklist, so such an
13	 * address is a 400 via {@link MissingFieldsException}. Runs after {@link NormalizeEmail}, so the
14	 * email is already syntactically valid and lower-cased. An absent or blank email passes through.
15	 */
16	public class RejectDisposableEmail {
17	
18	    private static final Set<String> BLOCKED =
19	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    public void service(@Val OwnerFieldsDto request) throws MissingFieldsException {
22	        String email = request.getEmail();
23	        if (email == null || email.isBlank()) {
24	            return;
25	        }
26	        String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
27	        if (BLOCKED.contains(domain)) {
28	            throw new MissingFieldsException(List.of("email"));
29	        }
30	    }
31	}
