1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	import java.util.Locale;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
9	
10	/**
11	 * Canonicalises the address whenever an owner is created: whitespace is trimmed and collapsed,
12	 * the text is upper-cased and common abbreviations are expanded ({@code ST}->{@code STREET},
13	 * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). The normalized value is stored back on
14	 * the request so it is persisted and returned as {@code address}, and so every downstream
15	 * comparison (household duplicate detection, the shared household id) sees the canonical form. An
16	 * address that is blank after normalization is rejected with 400 via {@link MissingFieldsException}.
17	 */
18	public class NormalizeAddress {
19	
20	    public void service(@Val OwnerFieldsDto request) throws MissingFieldsException {
21	        String line1 = normalize(request.getAddressLine1());
22	        if (line1 != null && !line1.isBlank()) {
23	            request.setAddressLine1(line1);
24	            String line2 = normalize(request.getAddressLine2());
25	            String composed = line1;
26	            if (line2 != null && !line2.isBlank()) {
27	                request.setAddressLine2(line2);
28	                composed = line1 + " " + line2;
29	            }
30	            request.setAddress(composed);
31	            return;
32	        }
33	        String flat = normalize(request.getAddress());
34	        if (flat == null || flat.isBlank()) {
35	            throw new MissingFieldsException(List.of("address"));
36	        }
37	        request.setAddress(flat);
38	    }
39	
40	    private static String normalize(String value) {
41	        if (value == null) {
42	            return null;
43	        }
44	        return value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT)
45	                .replaceAll("\\bST\\b", "STREET")
46	                .replaceAll("\\bRD\\b", "ROAD")
47	                .replaceAll("\\bAVE\\b", "AVENUE");
48	    }
49	}
