1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
10	
11	/**
12	 * Consolidated duplicate check: the former telephone, email and household checks are now a single
13	 * equality on the identity key ({@link IdentityKey}). Two owners are duplicates only when their
14	 * telephone and email both match, so members of the same household with different telephones have
15	 * different keys and are both allowed. Rejects a collision with a 409 via
16	 * {@link DuplicateIdentityException}.
17	 */
18	public class EnsureUniqueIdentity {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateIdentityException {
22	        String telephone = request.getTelephone();
23	        String email = normalizeEmail(request.getEmail());
24	        for (Owner owner : ownerRepository.findAll()) {
25	            if (!owner.isDeleted() && telephone.equals(owner.getTelephone())
26	                    && email.equals(normalizeEmail(owner.getEmail()))) {
27	                throw new DuplicateIdentityException(telephone + "|" + email);
28	            }
29	        }
30	    }
31	
32	    private static String normalizeEmail(String email) {
33	        return email == null || email.isBlank() ? "" : email.toLowerCase(Locale.ROOT);
34	    }
35	}
