5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
8	
9	/**
10	 * Rejects a create request whose city (compared case-insensitively) already holds
11	 * {@value #CAPACITY} or more owners, so a full city is a 409 via {@link CityAtCapacityException}.
12	 */
13	public class EnsureCityCapacity {
14	
15	    private static final int CAPACITY = 50;
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws CityAtCapacityException {
19	        String city = request.getCity();
20	        long inCity = ownerRepository.findAll().stream()
21	            .filter(owner -> city != null && city.equalsIgnoreCase(owner.getCity()))
22	            .count();
23	        if (inCity >= CAPACITY) {
24	            throw new CityAtCapacityException(city);
25	        }
26	    }
27	}
