13	public class BuildOwner {
14	
15	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
16	            throws MissingFieldsException {
17	        Owner owner = ownerMapper.toOwner(request);
18	        LocalDate supplied = owner.getRegistrationDate();
19	        if (supplied != null && supplied.isAfter(LocalDate.now())) { // future date: reject as 400
20	            throw new MissingFieldsException(List.of("registrationDate"));
21	        }
22	        LocalDate date = supplied != null ? supplied : LocalDate.now();
23	        owner.setRegistrationDate(BusinessDay.roll(date)); // skip weekends and public holidays
24	        built.set(owner);
25	    }
26	}
