10	/**
11	 * Rejects a create request once {@value #DAILY_LIMIT} or more owners already carry the new owner's
12	 * (adjusted business-day) registrationDate, so exceeding the daily cap is a 429 via
13	 * {@link DailyLimitExceededException}.
14	 */
15	public class EnsureDailyLimit {
16	
17	    private static final int DAILY_LIMIT = 100;
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DailyLimitExceededException {
20	        LocalDate day = owner.getRegistrationDate();
21	        long registeredToday = ownerRepository.findAll().stream()
22	            .filter(existing -> day.equals(existing.getRegistrationDate()))
23	            .count();
24	        if (registeredToday >= DAILY_LIMIT) {
25	            throw new DailyLimitExceededException(registeredToday);
26	        }
27	    }
28	}
