1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Locality;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Assigns the owner's {@code customerCode} as {@code <REGION>-<HASH8>}: REGION is the
13	 * region code for the owner (postcode-derived, city as fallback) and HASH8 is the first
14	 * eight upper-case hex characters of SHA-256 over (normalized telephone + last name). No
15	 * sequence number is used, so the identity is stable and city-count independent.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner) {
20	        String region = Locality.of(owner.getCity(), owner.getPostcode());
21	        owner.setCustomerCode(region + "-" + hash8(owner.getTelephone() + owner.getLastName()));
22	    }
23	
24	    private static String hash8(String value) {
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
27	            StringBuilder hex = new StringBuilder();
28	            for (int i = 0; hex.length() < 8; i++) {
29	                hex.append(String.format("%02X", digest[i]));
30	            }
31	            return hex.substring(0, 8);
32	        }
33	        catch (NoSuchAlgorithmException e) {
34	            throw new IllegalStateException(e);
35	        }
36	    }
37	}
