1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Ensures the owner's {@code customerCode} is unique. When the code computed by
12	 * {@link AssignCustomerCode} collides with an existing owner's {@code customerCode}, appends
13	 * {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique. Runs before the owner
14	 * is saved, so {@code findAll()} sees only the existing owners.
15	 */
16	public class DeduplicateCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        Set<String> taken = new HashSet<>();
20	        for (Owner existing : ownerRepository.findAll()) {
21	            taken.add(existing.getCustomerCode());
22	        }
23	        String base = owner.getCustomerCode();
24	        String candidate = base;
25	        for (int n = 2; taken.contains(candidate); n++) {
26	            candidate = base + "-" + n;
27	        }
28	        owner.setCustomerCode(candidate);
29	    }
30	}
