1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the owner's {@code namesakeCount}: the number of existing owners (before this create)
9	 * whose first and last name match, compared case-insensitively. Runs before the owner is saved,
10	 * so {@code findAll()} sees only the existing owners.
11	 */
12	public class AssignNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = normalize(owner.getFirstName());
16	        String lastName = normalize(owner.getLastName());
17	        int count = 0;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (firstName.equals(normalize(existing.getFirstName()))
20	                    && lastName.equals(normalize(existing.getLastName()))) {
21	                count++;
22	            }
23	        }
24	        owner.setNamesakeCount(count);
25	    }
26	
27	    private static String normalize(String value) {
28	        return value == null ? "" : value.trim().toLowerCase();
29	    }
30	}
