3	import java.time.LocalDate;
4	import java.util.Set;
5	
6	/** Business-day calendar: rolls a date forward over weekends and fixed public holidays. */
7	final class BusinessDay {
8	
9	    /** Fixed public holidays that the business-day roll skips. */
10	    private static final Set<LocalDate> HOLIDAYS = Set.of(
11	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
12	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
13	            LocalDate.parse("2026-12-28"));
14	
15	    private BusinessDay() {
16	    }
17	
18	    /** The given date, or the next day that is neither a weekend nor a listed holiday. */
19	    static LocalDate roll(LocalDate date) {
20	        while (date.getDayOfWeek().getValue() > 5 || HOLIDAYS.contains(date)) {
21	            date = date.plusDays(1);
22	        }
23	        return date;
24	    }
25	}
